ROOT=Path(__file__).absolute().parents[1]
digest=lambda data:hashlib.sha256(data).hexdigest()

def require(value,message):
    if not value:raise ValueError(message)

# Lexical spelling only: no resolution, stat, file contents or validity cached.
_ANCESTRY_CACHE_ENTRIES = 256

@lru_cache(maxsize=_ANCESTRY_CACHE_ENTRIES)
def _lexical_ancestry(root,absolute):
    path=Path(absolute);root=Path(root)
    require(path==root or root in path.parents,'Structural graph path escapes project root')
    return tuple(os.fspath(item) for item in (path,*path.parents))

def _check_directory(path):
    # Fresh metadata, never cached validity. Windows symbolic-link attributes
    # describe the link itself; reject every reparse point before accepting DIR.
    # https://learn.microsoft.com/windows/win32/api/fileapi/nf-fileapi-getfileattributesw
    if _directory_attributes is not None:
        attributes = _directory_attributes(path)
        if attributes != 0xffffffff:
            require(not attributes & 0x400, 'Structural graph path crosses reparse point')
            require(attributes & 0x10, 'Structural graph ancestry is not directory')
            return
    # Preserve original errors and UNC-share-root behavior when the lightweight
    # query is unavailable/fails. The actual leaf always retains full lstat.
    info = os.lstat(path)
    require(not stat.S_ISLNK(info.st_mode) and not getattr(info, 'st_file_attributes', 0) & 0x400,
            'Structural graph path crosses reparse point')
    require(stat.S_ISDIR(info.st_mode), 'Structural graph ancestry is not directory')

def _inspect_ordinary(path,required=True):
    path=Path(os.path.abspath(path));leaf=None
    for index,item in enumerate(_lexical_ancestry(os.fspath(ROOT),os.fspath(path))):
        try:
            if index:
                _check_directory(item)
                continue
            info=os.lstat(item)
        except FileNotFoundError:
            if index==0 and not required:continue
            raise ValueError('Structural graph required ancestry/input missing')
        require(not stat.S_ISLNK(info.st_mode) and not getattr(info,'st_file_attributes',0)&0x400,
                'Structural graph path crosses reparse point')
        leaf=info
    return path,leaf

def ordinary(path,required=True):
    return _inspect_ordinary(path,required)[0]

def read(rel):
    path,info=_inspect_ordinary(ROOT/rel)
    require(stat.S_ISREG(info.st_mode),'Structural graph required ordinary file missing')
    return path.read_bytes()

def read_target(rel,allow_absent=False):
    # Absence is legal only for the one explicit pinned originalAbsent header.
    path,info=_inspect_ordinary(ROOT/rel,required=not allow_absent)
    if info is None:return None
    require(stat.S_ISREG(info.st_mode),'Structural graph target must be an ordinary file')
    return path.read_bytes()


def load_pinned(rel,expected):
    # Text contracts: identity is line-ending normalized (a Windows CRLF checkout and a
    # Linux/macOS LF checkout of the same committed manifest must agree).
    raw=read(rel);require(digest(raw.replace(b'\r\n',b'\n'))==expected,'Structural graph contract identity mismatch: '+rel)
    return json.loads(raw)

def _parse_uncached(payload,path,added,deleted):
    require(b'\r' not in payload and b'\0' not in payload,'Structural graph payload must be LF text')
    lines=payload.splitlines(keepends=True)
    require(len(lines)>2 and lines[:2]==[('--- a/'+path+'\n').encode(),('+++ b/'+path+'\n').encode()],
            'Structural graph payload exact path/header mismatch')
    hunks=[];index=2;actual_add=actual_delete=0
    while index<len(lines):
        match=re.fullmatch(rb'@@ -(\d+)(?:,(\d+))? \+(\d+)(?:,(\d+))? @@[^\n]*\n',lines[index])
        require(match,'Structural graph unexpected payload directive')
        oldstart,newstart=int(match[1]),int(match[3]);oldcount=int(match[2] or b'1');newcount=int(match[4] or b'1')
        index+=1;body=[]
        while index<len(lines) and not lines[index].startswith(b'@@ '):
            line=lines[index];require(line[:1] in (b' ',b'+',b'-') and line.endswith(b'\n'),'Structural graph malformed hunk')
            body.append(line);actual_add+=line[:1]==b'+';actual_delete+=line[:1]==b'-';index+=1
        require(sum(x[:1] in (b' ',b'-') for x in body)==oldcount and sum(x[:1] in (b' ',b'+') for x in body)==newcount,
                'Structural graph hunk line counts mismatch')
        hunks.append((oldstart,oldcount,newstart,newcount,tuple(body)))
    require(hunks and (actual_add,actual_delete)==(added,deleted),'Structural graph independent numstat mismatch')
    return tuple(hunks)

def _apply_uncached(hunks,source,reverse=False):
    source=source.splitlines(keepends=True);output=[];cursor=0
    for oldstart,oldcount,newstart,newcount,body in hunks:
        index=max(0,(newstart if reverse else oldstart)-1)
        require(cursor<=index<=len(source),'Structural graph overlapping/out-of-range hunk')
        output.extend(source[cursor:index]);cursor=index
        for line in body:
            kind,content=line[:1],line[1:]
            if reverse:kind={b'+':b'-',b'-':b'+',b' ':b' '}[kind]
            if kind in (b' ',b'-'):
                require(cursor<len(source) and source[cursor]==content,'Structural graph exact hunk preimage mismatch')
                cursor+=1
            if kind in (b' ',b'+'):output.append(content)
    return b''.join(output+source[cursor:])

# CONTROL tooling only. These caches retain PURE immutable byte transforms,
# never resolved-path checks, filesystem results, manifest validity or target
# state. The path string is only expected patch-header text, not filesystem proof. Every
# preflight still reads/hashes/rechecks every authoritative input and every
# reverse/forward endpoint. Limits bound entries AND accepted byte sizes.
_PARSE_CACHE_ENTRIES = 128  # Bounded headroom for the current99 immutable payload stages.
_REPLAY_CACHE_ENTRIES = 256  # Current99 forward/reverse pairs fit; byte caps remain unchanged.
_MAX_CACHED_PATCH_BYTES = 64 * 1024
_MAX_CACHED_SOURCE_BYTES = 256 * 1024

class _ParsedHunks(tuple):
    __slots__ = ()  # Cache-produced deeply immutable int/tuple/bytes only.

@lru_cache(maxsize=_PARSE_CACHE_ENTRIES)
def _parse_cached(payload,path,added,deleted):
    return _ParsedHunks(_parse_uncached(payload,path,added,deleted))

def parse(payload,path,added,deleted):
    if (type(payload) is bytes and len(payload)<=_MAX_CACHED_PATCH_BYTES and
            type(path) is str and type(added) is int and type(deleted) is int):
        return _parse_cached(payload,path,added,deleted)
    return _parse_uncached(payload,path,added,deleted)

@lru_cache(maxsize=_REPLAY_CACHE_ENTRIES)
def _apply_cached(hunks,source,reverse):
    return _apply_uncached(hunks,source,reverse)

def apply(hunks,source,reverse=False):
    if (type(hunks) is _ParsedHunks and type(source) is bytes and
            len(source)<=_MAX_CACHED_SOURCE_BYTES and type(reverse) is bool):
        return _apply_cached(hunks,source,reverse)
    # Mutable/legacy caller structures and oversize buffers remain uncached.
    return _apply_uncached(hunks,source,reverse)

def preflight():
    lock=json.loads(read('dependencies.lock.json'))
    dependency=[item for item in lock['dependencies'] if item['name']=='tracktion_engine']
    require(len(dependency)==1 and dependency[0]['revision']==APPROVED['revision'] and
            dependency[0]['sourceDirectory']==APPROVED['sourceDirectory'] and dependency[0]['sha256']==APPROVED['archiveSha256'],
            'Structural graph pinned dependency mismatch')
    contracts={rel:load_pinned(rel,expected) for rel,expected in APPROVED['requiredContractSha256'].items()}
    for contract in contracts.values():
        require(contract['dependency']=='tracktion_engine' and contract['revision']==APPROVED['revision'] and
                contract['sourceDirectory']==APPROVED['sourceDirectory'],'Structural graph predecessor pin mismatch')
    # Exactly the reviewed families; overlapping targets form only the
    # explicit approved successor chain, never an arbitrary manifest extension.
    chains={};source='vendor/source/'+APPROVED['sourceDirectory']+'/'
    # Exact external reader contract. Its normal JUCE guard still applies its
    # native files later in the dependency chain; no source-admission activation.
    reader=APPROVED['sourceBurstJuce'];reader_contract=load_pinned(reader['path'],reader['sha256'])
    juce=[item for item in lock['dependencies'] if item['name']==reader['dependency']]
    require(len(juce)==1 and all(reader_contract.get(k)==reader[k] for k in
                ('dependency','revision','sourceDirectory','archiveSha256')) and
            juce[0]['revision']==reader['revision'] and juce[0]['sourceDirectory']==reader['sourceDirectory'] and
            juce[0]['sha256']==reader['archiveSha256'],'Source admission pinned reader contract mismatch')
    # DeviceManager has an independently guarded CONTROL-fence predecessor.
    # Seed its two exact stages, allowing fresh and mixed known chains WITHOUT
    # invoking a PS applier or weakening the four source-admission preimages.
    fence=APPROVED['sourceBurstFence'];fence_contract=contracts[fence['path']]
    expected=[{k:v for k,v in e.items() if k not in ('addedLines','deletedLines','lineage')} for e in fence['files']]
    require(fence_contract['files']==expected and fence_contract['controlPreparationFence'] is True,
            'Source admission exact preparation-fence stages mismatch')
    for entry in fence['files']:
        payload=read(entry['patch']);require(digest(payload)==entry['patchSha256'],'Preparation-fence stage payload identity mismatch')
        hunks=parse(payload,entry['path'],entry['addedLines'],entry['deletedLines'])
        chains[entry['path']]=[dict(entry=entry,hunks=hunks)]
    for family in APPROVED['families']:
        if family['path']=='patches/tracktion-context-wait-deadline/manifest.json':
            require(len(chains)==38 and sum(map(len,chains.values()))==112,
                    'Structural graph historical continuation exact 38 targets/112 reviewed stages required')
        if family['path']=='patches/tracktion-finished-forward-continuation/manifest.json':
            require(len(chains)==38 and sum(map(len,chains.values()))==111,
                    'Structural graph historical render policy exact 38 targets/111 reviewed stages required')
        if family['path']=='patches/tracktion-render-worker-policy/manifest.json':
            require(len(chains)==37 and sum(map(len,chains.values()))==110,
                    'Structural graph historical production-source exact 37 targets/110 reviewed stages required')
        if family['path']=='patches/tracktion-production-source-gate/manifest.json':
            require(len(chains)==37 and sum(map(len,chains.values()))==104,
                    'Structural graph historical legacy-MIDI exact 37 targets/104 reviewed stages required')
        if family['path']=='patches/tracktion-legacy-midi-runtime/manifest.json':
            require(len(chains)==37 and sum(map(len,chains.values()))==101,
                    'Structural graph historical source-time exact 37 targets/101 reviewed stages required')
        if family['path']=='patches/tracktion-source-render-time/manifest.json':
            require(len(chains)==37 and sum(map(len,chains.values()))==99,
                    'Structural graph historical stable-MIDI exact 37 targets/99 reviewed stages required')
        if family['path']=='patches/tracktion-stable-track-midi/manifest.json':
            require(len(chains)==37 and sum(map(len,chains.values()))==94,
                    'Structural graph historical zero-channel exact 37 targets/94 reviewed stages required')
        if family['path']=='patches/tracktion-zero-channel-delay/manifest.json':
            require(len(chains)==37 and sum(map(len,chains.values()))==92,
                    'Structural graph historical whole-exchange exact 37 targets/92 reviewed stages required')
        if family['path']=='patches/tracktion-whole-source-exchange/manifest.json':
            require(len(chains)==37 and sum(map(len,chains.values()))==89,
                    'Structural graph historical empty-arranger exact 37 targets/89 reviewed stages required')
        if family['path']=='patches/tracktion-empty-arranger-proof/manifest.json':
            require(len(chains)==37 and sum(map(len,chains.values()))==88,
                    'Structural graph historical context-memory exact 37 targets/88 reviewed stages required')
        if family['path']=='patches/tracktion-context-memory-policy/manifest.json':
            require(len(chains)==37 and sum(map(len,chains.values()))==83,
                    'Structural graph historical audio-zero exact 37 targets/83 reviewed stages required')
        if family['path']=='patches/tracktion-prepared-audio-zero/manifest.json':
            require(len(chains)==37 and sum(map(len,chains.values()))==80,
                    'Structural graph historical app-bridge exact 37 targets/80 reviewed stages required')
        if family['path']=='patches/tracktion-app-source-port-bridge/manifest.json':
            require(len(chains)==37 and sum(map(len,chains.values()))==75,
                    'Structural graph historical final-output exact 37 targets/75 reviewed stages required')
        if family['path']=='patches/tracktion-plugin-final-output/manifest.json':
            require(len(chains)==37 and sum(map(len,chains.values()))==69,
                    'Structural graph historical MIDI exact 37 targets/69 reviewed stages required')
        if family['path']=='patches/tracktion-native-midi-ingress/manifest.json':
            require(len(chains)==35 and sum(map(len,chains.values()))==64,
                    'Structural graph pre-MIDI exact 35 targets/64 reviewed stages required')
        if family['path']=='patches/tracktion-inverse-stage-seal/manifest.json':
            require(len(chains)==35 and sum(map(len,chains.values()))==63,
                    'Structural graph first-inverse exact 35 targets/63 reviewed stages required')
        if family['path']=='patches/tracktion-inverse-stage-residual/manifest.json':
            require(len(chains)==35 and sum(map(len,chains.values()))==61,
                    'Structural graph zero-history exact 35 targets/61 reviewed stages required')
        if family['path']=='patches/tracktion-zero-history-creation/manifest.json':
            require(len(chains)==35 and sum(map(len,chains.values()))==59,
                    'Structural graph historical exact 35 targets/59 reviewed stages required')
        manifest=load_pinned(family['path'],family['sha256'])
        require(manifest['schema']==1 and manifest['productionEnabled'] is family.get('productionEnabled',False) and manifest['files']==family['files'] and
                manifest['revision']==APPROVED['revision'] and manifest['archiveSha256']==APPROVED['archiveSha256'],
                'Structural graph family contract mismatch')
        contracts[family['path']]=manifest
        for entry in family['files']:
            path=entry['path'];require(path.startswith('modules/') and '\\' not in path and
                all(part not in ('','..','.') for part in path.split('/')),'Structural graph invalid reviewed path')
            payload=read(entry['patch']);require(digest(payload)==entry['patchSha256'],'Structural graph payload exact identity mismatch')
            hunks=parse(payload,path,entry['addedLines'],entry['deletedLines'])
            if entry.get('originalAbsent',False):
                require(family['path']=='patches/tracktion-send-gain-block/manifest.json' and path=='modules/tracktion_graph/tracktion_graph/tracktion_SendGainBlock.h' and
                        entry['originalSha256']=='e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855' and not entry['lineage'],
                        'Structural graph original absence is not the exact reviewed new header')
            prior=None
            for rel in entry['lineage']:
                require(rel in contracts,'Structural graph unvalidated predecessor contract')
                rows=[item for item in contracts[rel]['files'] if item['path']==path]
                require(len(rows)==1,'Structural graph missing exact predecessor target')
                if prior is not None:require(rows[0]['originalSha256']==prior,'Structural graph broken explicit predecessor chain')
                prior=rows[0]['patchedSha256']
            if prior is not None:require(prior==entry['originalSha256'],'Structural graph successor does not follow predecessor')
            chain=chains.setdefault(path,[])
            if chain:require(chain[-1]['entry']['patchedSha256']==entry['originalSha256'],
                             'Structural graph overlapping target is not exact reviewed successor')
            chain.append(dict(entry=entry,hunks=hunks))
    # Pinned source dependencies are part of the predecessor contract even when
    # a later family proves its native bytes without running a PS predecessor.
    for contract in contracts.values():
        dependencies=list(contract.get('sourceDependencies',[]))
        if 'sourceDependency' in contract:dependencies.append(contract['sourceDependency'])
        for item in dependencies:
            require(item['mode']=='content' and item['path'].startswith('src/'),
                    'Structural graph unexpected source dependency mode/path')
            require(digest(read(item['path']).replace(b'\r\n',b'\n'))==item['sha256'],
                    'Structural graph predecessor source content identity mismatch')
    require(len(chains)==38 and sum(map(len,chains.values()))==113,
            'Structural graph exact 38 targets/113 reviewed stages required')
    changes=[]
    for path,chain in chains.items():
        absent=chain[0]['entry'].get('originalAbsent',False)
        raw=read_target(source+path,absent);identity=digest(raw if raw is not None else b'')
        require(not (absent and raw is not None and identity==chain[0]['entry']['originalSha256']),
                'Structural graph reviewed new header must be absent, not an empty impostor')
        identities=[chain[0]['entry']['originalSha256']]+[item['entry']['patchedSha256'] for item in chain]
        require(identities.count(identity)==1,'Structural graph unknown/ambiguous vendor bytes preserved: '+path)
        position=identities.index(identity);original=raw if raw is not None else b''
        for item in reversed(chain[:position]):
            original=apply(item['hunks'],original,True)
            require(digest(original)==item['entry']['originalSha256'],'Structural graph exact chained reverse mismatch')
        final=original
        for item in chain:
            require(digest(final)==item['entry']['originalSha256'],'Structural graph exact chained preimage mismatch')
            final=apply(item['hunks'],final)
            require(digest(final)==item['entry']['patchedSha256'],'Structural graph exact chained postimage mismatch')
        changes.append(dict(entry=chain[-1]['entry'],chain=chain,rel=source+path,before=raw,final=final,
                            pending=identity!=chain[-1]['entry']['patchedSha256']))
    ready=contracts['patches/tracktion-ready-graph/manifest.json']
    for entry in ready['files']:
        following=[item for item in changes if item['entry']['path']==entry['path']]
        require(len(following)==1 and any('patches/tracktion-ready-graph/manifest.json' in row['entry']['lineage'] and
                    row['entry']['originalSha256']==entry['patchedSha256'] for row in following[0]['chain']),
                'Structural graph ready-holder exact successor lineage missing')
    return changes

def main():
    parser=argparse.ArgumentParser();parser.add_argument('--verify-only',action='store_true')
    parser.add_argument('--known-successor',nargs=3,metavar=('PREDECESSOR','PATH','CURRENT_SHA256'))
    args=parser.parse_args()
    if args.verify_only or args.known_successor:
        changes=preflight()
    else:
        sys.path.insert(0,str(ROOT/'scripts'))
        from dev_support import EngineeringOwner
        with EngineeringOwner(ROOT,'guarded structural graph dependency integration'):
            changes=preflight()
            # Recheck EVERY input and ancestry before FIRST write. Unknown/mixed
            # changes refuse without partial application. I/O interruption can
            # leave known original/final mix; next strict invocation diagnoses it.
            for item in changes:require(read_target(item['rel'],item['chain'][0]['entry'].get('originalAbsent',False))==item['before'],'Structural graph vendor changed during preflight')
            for item in changes:
                if not item['pending']:continue
                path=ordinary(ROOT/item['rel'],required=item['before'] is not None);temporary=None
                try:
                    fd,name=tempfile.mkstemp(prefix='.vibera-structural-',suffix='.tmp',dir=path.parent);temporary=Path(name)
                    with os.fdopen(fd,'wb') as stream:stream.write(item['final']);stream.flush();os.fsync(stream.fileno())
                    require(read_target(item['rel'],item['chain'][0]['entry'].get('originalAbsent',False))==item['before'],'Structural graph target changed before exact replacement')
                    ordinary(temporary)
                    os.replace(temporary,path);temporary=None
                    require(digest(read(item['rel']))==item['entry']['patchedSha256'],'Structural graph final raw identity mismatch')
                finally:
                    if temporary is not None:
                        ordinary(temporary)
                        temporary.unlink(missing_ok=True)
    if args.known_successor:
        predecessor,path,current=args.known_successor
        matches=[item for item in changes if item['entry']['path']==path]
        require(len(matches)==1 and any(predecessor in row['entry']['lineage'] and
                    current==row['entry']['patchedSha256'] for row in matches[0]['chain']) and
                digest(matches[0]['before'])==current,
                'Structural graph requested successor is not exact reviewed current final')
    print(json.dumps({'verified':True,'mode':'known_successor' if args.known_successor else 'verify_only' if args.verify_only else 'apply',
                      'vendorTargets':len(changes),'pendingBefore':sum(item['pending'] for item in changes),
                      'productionEnabled':False, # Structural handoff opt-ins remain independent.
                      'renderWorkerPolicyEnabled':True}))

if __name__=='__main__':
    try:main()
    except Exception as error:
        print('FAIL structural graph guard: '+str(error),file=sys.stderr);raise SystemExit(1)
